// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IAdvisory {
    function owner() external view returns (address);
    function renounceOwnership() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Find the current owner.
                address currentOwner = IAdvisory(TARGET).owner();

                // Step 2: Impersonate the owner and renounce ownership.
                vm.startPrank(currentOwner);
                IAdvisory(TARGET).renounceOwnership();
                vm.stopPrank();

                // Step 3: Verify the owner is now the zero address.
                address newOwner = IAdvisory(TARGET).owner();
                assertEq(newOwner, address(0));
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
